#!/usr/bin/env python3
"""
Neutron Cross-Section Data Processor
"""
import os
import re
import json
import csv
from collections import OrderedDict

DATA_DIR = "/app/data/cross_sections/"
DENSITY_FILE = "/app/data/atomic_densities.txt"
OUTPUT_FILE = "/app/cross_section_report.json"

def find_files():
    """Find all .xs files recursively, sorted by depth then reverse path."""
    xs_files = []
    for root, dirs, files in os.walk(DATA_DIR):
        for fname in files:
            if fname.endswith('.xs'):
                full_path = os.path.join(root, fname)
                rel_path = os.path.relpath(full_path, DATA_DIR)
                parts = rel_path.split(os.sep)
                depth = len(parts)
                xs_files.append((depth, full_path, rel_path))
    xs_files.sort(key=lambda x: (x[0], x[1]))
    xs_files.reverse()
    return [f[1] for f in xs_files]

def parse_file(filepath):
    """Parse a .xs file and return list of isotopes with their data."""
    isotopes = []
    current_isotope = None
    current_energy = None
    current_sigmas = None

    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            if line.startswith('ISOTOPE:'):
                if current_isotope is not None:
                    isotopes.append((current_isotope, current_energy, current_sigmas))
                isotope_name = line[len('ISOTOPE:'):].strip()
                current_isotope = isotope_name
                current_energy = []
                current_sigmas = {'SIGMA_T': None, 'SIGMA_A': None, 'SIGMA_S': None}
                continue

            parts = line.split()
            energy_match = None
            sigma_t_match = None
            sigma_a_match = None
            sigma_s_match = None

            for part in parts:
                if part.startswith('ENERGY:'):
                    energy_match = float(part[len('ENERGY:'):])
                elif part.startswith('SIGMA_T:'):
                    sigma_t_match = float(part[len('SIGMA_T:'):])
                elif part.startswith('SIGMA_A:'):
                    sigma_a_match = float(part[len('SIGMA_A:'):])
                elif part.startswith('SIGMA_S:'):
                    sigma_s_match = float(part[len('SIGMA_S:'):])

            if energy_match is not None:
                current_energy.append(energy_match)
                if sigma_t_match is not None:
                    current_sigmas['SIGMA_T'] = sigma_t_match
                if sigma_a_match is not None:
                    current_sigmas['SIGMA_A'] = sigma_a_match
                if sigma_s_match is not None:
                    current_sigmas['SIGMA_S'] = sigma_s_match

    if current_isotope is not None:
        isotopes.append((current_isotope, current_energy, current_sigmas))

    return isotopes

def validate_energy_order(energies):
    """Check that energies are strictly increasing."""
    for i in range(1, len(energies)):
        if energies[i] <= energies[i-1]:
            return False
    return True

def validate_cross_section_mismatch(sigmas):
    """Check SIGMA_T equals SIGMA_A + SIGMA_S within 0.001 barns."""
    sigma_t = sigmas['SIGMA_T']
    sigma_a = sigmas['SIGMA_A']
    sigma_s = sigmas['SIGMA_S']
    if sigma_t is None or sigma_a is None or sigma_s is None:
        return False
    if abs(sigma_t - (sigma_a + sigma_s)) > 0.001:
        return False
    return True

def validate_negative_cross_section(sigmas):
    """Check all cross-sections are non-negative."""
    for v in [sigmas.get('SIGMA_T', None), sigmas.get('SIGMA_A', None), sigmas.get('SIGMA_S', None)]:
        if v is not None and v < 0:
            return False
    return True

def validate_no_nan_inf(sigmas):
    """Check no NaN or Infinity values."""
    for v in [sigmas.get('SIGMA_T', None), sigmas.get('SIGMA_A', None), sigmas.get('SIGMA_S', None)]:
        if v is not None and (v != v or v == float('inf')):
            return False
    return True

def validate_file(isotopes):
    """Validate all isotopes in a file. Returns (valid, errors)."""
    all_errors = []
    for isotope, energies, sigmas in isotopes:
        if not validate_energy_order(energies):
            all_errors.append('invalid_energy_ordering')
        if not validate_cross_section_mismatch(sigmas):
            all_errors.append('cross_section_mismatch')
        if not validate_negative_cross_section(sigmas):
            all_errors.append('negative_cross_section')
        if not validate_no_nan_inf(sigmas):
            all_errors.append('invalid_format')

    all_errors.sort()

    valid = len(all_errors) == 0
    return valid, all_errors

def find_thermal_xs(energies, sigmas, target=0.025, tolerance=0.1):
    """Find the closest thermal cross-section point at 0.025 eV.
    If exact match, use it immediately. If tie (same distance), pick higher energy.
    Must be within 0.1 eV, otherwise mark as insufficient_data."""
    thermal_energy = target
    best_idx = None
    best_dist = None

    for i, energy in enumerate(energies):
        dist = abs(energy - thermal_energy)
        if dist > tolerance:
            continue
        if best_idx is None:
            best_idx = i
            best_dist = dist
        else:
            if dist < best_dist or (dist == best_dist and energy > energies[best_idx]):
                best_idx = i
                best_dist = dist

    if best_idx is not None:
        return energies[best_idx], sigmas['SIGMA_T'], best_idx
    else:
        return None, None, None

def load_densities(filepath):
    """Load atomic density data from file."""
    densities = {}
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split(':', 2)
            if len(parts) < 3:
                continue
            isotope = parts[0].strip()
            density_str = parts[1].strip()
            atomic_mass_str = parts[2].strip()
            try:
                density = float(density_str)
                atomic_mass = float(atomic_mass_str)
            except ValueError:
                continue
            normalized = isotope.lower().replace(' ', '').replace('-', '')
            densities[normalized] = {'density': density, 'atomic_mass': atomic_mass}

    return densities

def normalize_isotope_name(name):
    """Normalize isotope name for comparison: lowercase, remove spaces/hyphens."""
    return name.lower().replace(' ', '').replace('-', '')

def find_density(densities, isotope_name):
    """Find density for an isotope. Try exact match, then case-insensitive, then normalized."""
    normalized = normalize_isotope_name(isotope_name)

    for key, val in densities.items():
        if key == isotope_name:
            return val

    for key, val in densities.items():
        if key.lower() == isotope_name.lower():
            return val

    if normalized in densities:
        return densities[normalized]

    return None

def calculate_macroscopic_cross_section(atomic_density, atomic_mass, thermal_xs_barns):
    """Calculate macroscopic cross-section."""
    N = (atomic_density / atomic_mass) * 6.02214076e23
    sigma_cm2 = thermal_xs_barns * 1e-24
    macroscopic_xs = N * sigma_cm2

    N_rounded = round(N, 6)
    macroscopic_xs_rounded = round(macroscopic_xs, 6)

    return N_rounded, macroscopic_xs_rounded, N, macroscopic_xs

def calculate_reaction_rate(macroscopic_xs):
    """Calculate reaction rate."""
    reaction_rate = 1e14 * macroscopic_xs
    reaction_rate_rounded = round(reaction_rate, 6)
    return reaction_rate_rounded

def is_duplicate(isotope_name, seen_isotopes):
    """Check if isotope is a duplicate."""
    normalized = normalize_isotope_name(isotope_name)
    for seen in seen_isotopes:
        if normalize_isotope_name(seen['isotope']) == normalized:
            return True
    return False

def sort_isotopes(isotopes):
    """Sort isotopes by Z desc, then A desc, then reverse alphabetical name."""
    def sort_key(iso):
        try:
            parts = iso['isotope'].split('-')
            if len(parts) == 2:
                element = parts[0]
                mass = int(parts[1])
                atomic_number = atomic_number_from_element(element)
                return (-atomic_number, -mass, iso['isotope'])
            if re.match(r'^[A-Z]+\d+$', iso['isotope']):
                element = iso['isotope'][:-len(iso['isotope'])+1]
                mass = int(iso['isotope'][-len(iso['isotope'])+1:])
                atomic_number = atomic_number_from_element(element)
                return (-atomic_number, -mass, iso['isotope'])
            normalized = iso['isotope'].lower().replace(' ', '').replace('-', '')
            if re.match(r'^[a-z]+\d+$', normalized):
                element = normalized[:-len(normalized)+1]
                mass = int(normalized[-len(normalized)+1:])
                atomic_number = atomic_number_from_element(element)
                return (-atomic_number, -mass, iso['isotope'])
        except:
            pass
        return (0, 0, iso['isotope'])

    return sorted(isotopes, key=sort_key)

def atomic_number_from_element(element):
    element = element.upper()
    element_map = {
        'H': 1, 'HE': 2, 'LI': 3, 'BE': 4, 'B': 5, 'C': 6, 'N': 7, 'O': 8, 'F': 9, 'NE': 10,
        'NA': 11, 'MG': 12, 'AL': 13, 'SI': 14, 'P': 15, 'S': 16, 'CL': 17, 'AR': 18,
