        'BI': 83, 'PO': 84, 'AT': 85, 'RN': 86, 'FR': 87, 'RA': 88, 'AC': 89, 'TH': 90,
        'PA': 91, 'U': 92, 'NP': 93, 'PU': 94, 'AM': 95, 'CM': 96, 'BK': 97, 'CF': 98,
        'ES': 99, 'FM': 100, 'MD': 101, 'NO': 102, 'LR': 103, 'RF': 104, 'DB': 105,
        'SG': 106, 'BH': 107, 'HS': 108, 'MT': 109, 'DS': 110, 'RG': 111, 'CN': 112,
        'NH': 113, 'FL': 114, 'MC': 115, 'LV': 116, 'TS': 117, 'OG': 118
    }
    return element_map.get(element, 0)

def main():
    xs_files = find_files()
    total_files = len(xs_files)

    densities = load_densities(DENSITY_FILE)

    seen_isotopes = OrderedDict()
    isotopes = []
    valid_files = 0
    invalid_files = 0

    for filepath in xs_files:
        parsed_isotopes = parse_file(filepath)

        valid, file_errors = validate_file(parsed_isotopes)

        if valid:
            valid_files += 1
        else:
            invalid_files += 1

        for isotope_name, energies, sigmas in parsed_isotopes:
            if is_duplicate(isotope_name, seen_isotopes):
                status = 'duplicate_isotope'
                atomic_density = None
                macroscopic_cross_section = None
                reaction_rate = None
                thermal_xs_barns = None
            else:
                seen_isotopes[isotope_name] = True

                density_info = find_density(densities, isotope_name)
                if density_info is None:
                    status = 'missing_density_data'
                    atomic_density = None
                    macroscopic_cross_section = None
                    reaction_rate = None
                    thermal_xs_barns = None
                else:
                    density = density_info['density']
                    atomic_mass = density_info['atomic_mass']

                    thermal_energy, thermal_sigmas_t, idx = find_thermal_xs(energies, sigmas, target=0.025, tolerance=0.1)
                    if thermal_energy is None:
                        status = 'insufficient_data'
                        atomic_density = None
                        macroscopic_cross_section = None
                        reaction_rate = None
                        thermal_xs_barns = None
                    else:
                        status = 'valid'
                        thermal_xs_barns = sigmas['SIGMA_T']
                        N_rounded, macroscopic_xs_rounded, N, macroscopic_xs = calculate_macroscopic_cross_section(density, atomic_mass, thermal_xs_barns)
                        reaction_rate = calculate_reaction_rate(macroscopic_xs_rounded)
                        atomic_density = N_rounded
                        macroscopic_cross_section = macroscopic_xs_rounded

                isotopes.append({
                    'isotope': isotope_name,
                    'source_file': os.path.relpath(filepath, DATA_DIR),
                    'status': status,
                    'atomic_density_atoms_cm3': atomic_density,
                    'macroscopic_cross_section_cm_minus1': macroscopic_cross_section,
                    'reaction_rate_reactions_cm3_s': reaction_rate,
                    'thermal_xs_barns': thermal_xs_barns,
                    'validation_errors': file_errors if status == 'valid' else []
                })

    sorted_isotopes = sort_isotopes(isotopes)

    total_isotopes = len(isotopes)
    valid_isotopes = sum(1 for iso in sorted_isotopes if iso['status'] == 'valid')
    invalid_isotopes = total_isotopes - valid_isotopes

    output = {
        'total_files': total_files,
        'valid_files': valid_files,
        'invalid_files': invalid_files,
        'total_isotopes': total_isotopes,
        'valid_isotopes': valid_isotopes,
        'invalid_isotopes': invalid_isotopes,
        'isotopes': sorted_isotopes
    }

    tmp_file = OUTPUT_FILE + '.tmp'
    with open(tmp_file, 'w') as f:
        json.dump(output, f, indent=2)

    os.rename(tmp_file, OUTPUT_FILE)

    print("Report generated successfully at", OUTPUT_FILE)
    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
